// kt-witness is scraped every 15s. A rate window still needs to span several
// scrapes — otherwise the delta is taken across whatever gap happens to fall
// out — so floor it at 1m, four scrapes. Longer ranges widen normally.
w = if int(v: v.windowPeriod) < 60000000000 then 1m else v.windowPeriod

from(bucket: "server")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r.stack == "kt-witness" and r._field == "kt_witness_cosignatures_total")
  |> group(columns: ["kind"])
  |> aggregateWindow(every: w, fn: last, createEmpty: false)
  |> keep(columns: ["_time", "_value", "kind"])
  |> derivative(unit: 1m, nonNegative: true)

