// Rate of a counter, at whatever resolution the view is zoomed to.
//
// Two things matter here and the first version got both wrong. Take the max
// WITHIN a window before differencing, not the mean of differences: the mean
// smears a step change — a machine joining the fleet — across the window and
// makes exactly the event this panel exists to show look like drift. And floor
// the window at 1m: kt-witness is scraped every 15s, so a shorter window takes
// a delta across whatever gap happens to fall out of the alignment.
w = if int(v: v.windowPeriod) < 60000000000 then 1m else v.windowPeriod

from(bucket: "server")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r.stack == "kt-witness" and r._field == "kt_witness_audit_verified_total")
  |> group(columns: ["origin"])
  |> aggregateWindow(every: w, fn: max, createEmpty: false)
  |> derivative(unit: 1h, nonNegative: true)
  |> keep(columns: ["_time", "_value", "origin"])
